// PHYSARUM DREAMS
// A slime-mould simulation after Jeff Jones (2010): thousands of simple agents sense a shared trail, steer toward the
// stronger side, step forward and leave more trail. The trail diffuses and fades. Veins, lace and loops grow from nothing.
// Variables are re-read every frame: temperament changes how the agents steer, memory how long a trail lasts, food adds
// lamps that pull the network about, colony restarts the swarm, density changes how many agents are awake.

const MW = 300, MH = 300, MAXA = 16000;
const DEG = Math.PI / 180;

// sa: sensor angle, sd: sensor distance (cells), ra: turn angle, ss: step size, bias: >0 favours turning left
const TEMPER = {
  'tidy veins':        { sa: 22, sd: 9,  ra: 45, ss: 1.0, bias: 0 },
  'curious lace':      { sa: 45, sd: 12, ra: 45, ss: 1.0, bias: 0 },
  'frenzied scribble': { sa: 60, sd: 5,  ra: 90, ss: 1.5, bias: 0 },
  'cautious loops':    { sa: 30, sd: 18, ra: 20, ss: 0.8, bias: 0 },
  'spiral dancers':    { sa: 15, sd: 15, ra: 60, ss: 1.2, bias: 0.35 },
  'dense moss':        { sa: 35, sd: 6,  ra: 30, ss: 0.7, bias: 0 },
  'ghost threads':     { sa: 10, sd: 25, ra: 15, ss: 1.2, bias: 0 },
  'brittle glass':     { sa: 70, sd: 10, ra: 70, ss: 1.0, bias: 0 },
  'slow ferns':        { sa: 28, sd: 14, ra: 25, ss: 0.6, bias: 0 },
  'comet tails':       { sa: 12, sd: 30, ra: 12, ss: 1.8, bias: 0 }
};

// decay: how much trail survives each frame; blur: how much each cell shares with its neighbours
// evict: where the trail is thicker than this, agents are sometimes sent back to the dish at random,
// which keeps the veins from fattening into a few motorways and the lace alive
const MEMORY = {
  'a goldfish':    { decay: 0.80,  blur: 0.55, evict: 5 },
  'a hummingbird': { decay: 0.84,  blur: 0.53, evict: 6 },
  'a mayfly':      { decay: 0.88,  blur: 0.50, evict: 7 },
  'a crow':        { decay: 0.91,  blur: 0.48, evict: 8 },
  'a heron':       { decay: 0.935, blur: 0.45, evict: 9 },
  'a tortoise':    { decay: 0.96,  blur: 0.42, evict: 11 },
  'an elephant':   { decay: 0.975, blur: 0.40, evict: 14 },
  'amber':         { decay: 0.992, blur: 0.35, evict: 22 }
};

const DENSITY = { 'a handful': 1500, 'a sparse swarm': 3500, 'a thin crowd': 5000, 'a swarm': 7000, 'a thick swarm': 9000,
                 'a crowd': 11000, 'a throng': 13500, 'a multitude': 16000 };

const PALETTES = {
  'bioluminescent blue': ['#02040c', '#06284a', '#0f78b0', '#5ce1e0', '#effffe'],
  'neon mycelium':       ['#04060a', '#0b3d2e', '#1fa56a', '#a6ff6e', '#f7ffd0'],
  'gold leaf':           ['#080604', '#3a2208', '#a86b16', '#f0b93c', '#fff6d0'],
  'blueprint':           ['#06112a', '#0e2f6b', '#2a63c4', '#8fb8ff', '#ffffff'],
  'infrared heat':       ['#0a0204', '#4a0a1a', '#c4232a', '#ff8a1f', '#fff0a8'],
  'milk and ink':        ['#f4f1ea', '#cfc8bb', '#8d8577', '#3e3a33', '#0d0c0a'],
  'rust and sage':       ['#0c0a08', '#3a2417', '#8a4a24', '#a9b58a', '#f0ecd4'],
  'ultramarine':         ['#030311', '#0b0b57', '#2a28c8', '#7a7dff', '#e6e7ff'],
  'jade smoke':          ['#030807', '#0c3a33', '#1f8a78', '#8fe0c8', '#f3fff9'],
  'electric rose':       ['#08020a', '#4a0a3a', '#d41a7a', '#ff7ab0', '#fff0f6']
};

let trail = new Float32Array(MW * MH), tmp = new Float32Array(MW * MH);
const ax = new Float32Array(MAXA), ay = new Float32Array(MAXA), ah = new Float32Array(MAXA);
let off, octx, img, bloom, bctx;
const lut = new Uint8ClampedArray(256 * 3);
let colonyKey = null, lutKey = null, stars = [];
let toneK = 0.5;

function rand(a, b) { return a + Math.random() * (b - a); }

function seedColony(kind) {
  trail.fill(0);
  const cx = MW / 2, cy = MH / 2;
  for (let i = 0; i < MAXA; i++) {
    const u = i / MAXA, a = Math.random() * 6.2832;
    if (kind === 'a ring facing out') { const th = u * 6.2832 * 7; ax[i] = cx + Math.cos(th) * MW * 0.22; ay[i] = cy + Math.sin(th) * MH * 0.22; ah[i] = th; }
    else if (kind === 'a burst from the centre') { ax[i] = cx + rand(-3, 3); ay[i] = cy + rand(-3, 3); ah[i] = a; }
    else if (kind === 'two rival camps') { const left = i % 2 === 0; ax[i] = (left ? MW * 0.28 : MW * 0.72) + rand(-14, 14); ay[i] = cy + rand(-14, 14); ah[i] = a; }
    else if (kind === 'a frame facing in') {
      const side = i % 4, t = Math.random();
      if (side === 0) { ax[i] = t * MW; ay[i] = 8; ah[i] = 1.5708; } else if (side === 1) { ax[i] = t * MW; ay[i] = MH - 8; ah[i] = -1.5708; }
      else if (side === 2) { ax[i] = 8; ay[i] = t * MH; ah[i] = 0; } else { ax[i] = MW - 8; ay[i] = t * MH; ah[i] = 3.1416; }
    }
    else if (kind === 'a cross') { if (i % 2) { ax[i] = rand(MW * 0.15, MW * 0.85); ay[i] = cy + rand(-4, 4); } else { ax[i] = cx + rand(-4, 4); ay[i] = rand(MH * 0.15, MH * 0.85); } ah[i] = a; }
    else if (kind === 'a spiral arm') { const th = u * 6.2832 * 3.2, r = 6 + u * MW * 0.4; ax[i] = cx + Math.cos(th) * r; ay[i] = cy + Math.sin(th) * r; ah[i] = th + 1.5708; }
    else if (kind === 'a gathering crowd') { ax[i] = Math.random() * MW; ay[i] = Math.random() * MH; ah[i] = Math.atan2(cy - ay[i], cx - ax[i]); }
    else { ax[i] = Math.random() * MW; ay[i] = Math.random() * MH; ah[i] = a; }   // 'a scatter'
  }
  stars = [];
  for (let k = 0; k < 7; k++) stars.push([rand(MW * 0.12, MW * 0.88), rand(MH * 0.12, MH * 0.88)]);
}

function buildLut(stops) {
  const cols = stops.map(h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)]);
  for (let i = 0; i < 256; i++) {
    const t = (i / 255) * (cols.length - 1), a = Math.floor(t), b = Math.min(cols.length - 1, a + 1), m = t - a;
    for (let ch = 0; ch < 3; ch++) lut[i * 3 + ch] = cols[a][ch] + (cols[b][ch] - cols[a][ch]) * m;
  }
}

function sample(x, y) {
  const ix = ((x % MW) + MW) % MW | 0, iy = ((y % MH) + MH) % MH | 0;
  return trail[iy * MW + ix];
}

function respawn(i) {
  ax[i] = Math.random() * MW; ay[i] = Math.random() * MH; ah[i] = Math.random() * 6.2832;
}

function stepAgents(n, T, evict) {
  const sa = T.sa * DEG, ra = T.ra * DEG, cSA = Math.cos(sa), sSA = Math.sin(sa), sd = T.sd, ss = T.ss;
  for (let i = 0; i < n; i++) {
    let x = ax[i], y = ay[i], h = ah[i];
    const c = Math.cos(h), s = Math.sin(h);
    const f = sample(x + c * sd, y + s * sd);
    const l = sample(x + (c * cSA - s * sSA) * sd, y + (s * cSA + c * sSA) * sd);
    const r = sample(x + (c * cSA + s * sSA) * sd, y + (s * cSA - c * sSA) * sd);
    if (f > l && f > r) { /* straight on */ }
    else if (f < l && f < r) h += (Math.random() < 0.5 + T.bias ? ra : -ra);
    else if (l > r) h += ra;
    else if (r > l) h -= ra;
    x += Math.cos(h) * ss; y += Math.sin(h) * ss;
    if (x < 0) x += MW; else if (x >= MW) x -= MW;
    if (y < 0) y += MH; else if (y >= MH) y -= MH;
    ax[i] = x; ay[i] = y; ah[i] = h;
    const idx = (y | 0) * MW + (x | 0);
    if (trail[idx] > evict && Math.random() < 0.2) respawn(i);
    else trail[idx] += 1;
  }
}

function lamp(x, y, strength) {
  const ix = x | 0, iy = y | 0;
  for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
    const px = ((ix + dx) % MW + MW) % MW, py = ((iy + dy) % MH + MH) % MH;
    trail[py * MW + px] += strength;
  }
}

function food(kind, t) {
  const cx = MW / 2, cy = MH / 2;
  if (kind === 'a single lamp') lamp(cx, cy, 9);
  else if (kind === 'a constellation of lamps') for (const s of stars) lamp(s[0], s[1], 7);
  else if (kind === 'an orbiting lamp') lamp(cx + Math.cos(t * 0.012) * MW * 0.3, cy + Math.sin(t * 0.012) * MH * 0.3, 10);
  else if (kind === 'a row of lamps') for (let k = 0; k < 9; k++) lamp(MW * (0.1 + k * 0.1), cy, 7);
  else if (kind === 'a pulsing lamp') lamp(cx, cy, 8 + 7 * Math.sin(t * 0.05));
  else if (kind === 'four corner lamps') { lamp(MW * 0.2, MH * 0.2, 8); lamp(MW * 0.8, MH * 0.2, 8); lamp(MW * 0.2, MH * 0.8, 8); lamp(MW * 0.8, MH * 0.8, 8); }
  else if (kind === 'a ring of lamps') for (let k = 0; k < 12; k++) lamp(cx + Math.cos(k * 0.5236) * MW * 0.3, cy + Math.sin(k * 0.5236) * MH * 0.3, 7);
}

function diffuseDecay(M) {
  const w = M.blur, keep = 1 - w, d = M.decay;
  // horizontal 3-tap into tmp, vertical 3-tap back, mixed with the original
  for (let y = 0; y < MH; y++) {
    const row = y * MW;
    for (let x = 0; x < MW; x++) {
      const xl = x === 0 ? MW - 1 : x - 1, xr = x === MW - 1 ? 0 : x + 1;
      tmp[row + x] = (trail[row + xl] + trail[row + x] + trail[row + xr]) * 0.3333;
    }
  }
  for (let y = 0; y < MH; y++) {
    const yu = (y === 0 ? MH - 1 : y - 1) * MW, yd = (y === MH - 1 ? 0 : y + 1) * MW, row = y * MW;
    for (let x = 0; x < MW; x++) {
      const blurred = (tmp[yu + x] + tmp[row + x] + tmp[yd + x]) * 0.3333;
      trail[row + x] = d * (keep * trail[row + x] + w * blurred);
    }
  }
}

function paint() {
  const data = img.data;
  for (let i = 0; i < MW * MH; i++) {
    const v = trail[i] * toneK;
    const t = 1 - 1 / (1 + v * 1.4);      // soft saturation, 0..1
    const c = ((t * 255) | 0) * 3, o = i * 4;
    data[o] = lut[c]; data[o + 1] = lut[c + 1]; data[o + 2] = lut[c + 2]; data[o + 3] = 255;
  }
  octx.putImageData(img, 0, 0);
}

p.setup = function () {
  p.createCanvas(800, 800);
  p.pixelDensity(1);
  p.frameRate(60);
  off = document.createElement('canvas'); off.width = MW; off.height = MH;
  octx = off.getContext('2d'); img = octx.createImageData(MW, MH);
  bloom = document.createElement('canvas'); bloom.width = 75; bloom.height = 75;
  bctx = bloom.getContext('2d');
  buildLut(PALETTES['bioluminescent blue']); lutKey = 'bioluminescent blue';
  seedColony('a scatter'); colonyKey = 'a scatter';
};

p.draw = function () {
  const temper = p.getSynthVar('temperament') || 'tidy veins';
  const memory = p.getSynthVar('memory') || 'a heron';
  const colony = p.getSynthVar('colony') || 'a scatter';
  const palette = p.getSynthVar('palette') || 'bioluminescent blue';
  const lamps = p.getSynthVar('food') || 'no food at all';
  const density = p.getSynthVar('density') || 'a swarm';

  if (colony !== colonyKey) { seedColony(colony); colonyKey = colony; }
  if (palette !== lutKey) { buildLut(PALETTES[palette] || PALETTES['bioluminescent blue']); lutKey = palette; }
  const T = TEMPER[temper] || TEMPER['tidy veins'];
  const M = MEMORY[memory] || MEMORY['a heron'];
  const n = DENSITY[density] || 7000;
  // how thick a trail may get before agents are sent home: the memory's own level, or three times what a crowd of this
  // size would lay down on average, whichever is more; the picture reaches white at that level
  const avg = (2 * n / (MW * MH)) / (1 - M.decay);
  const evict = Math.max(M.evict, 3 * avg);
  toneK = 2.2 / evict;

  stepAgents(n, T, evict);
  food(lamps, p.frameCount);
  stepAgents(n, T, evict);
  food(lamps, p.frameCount);
  for (let k = 0, m = Math.ceil(n * 0.004); k < m; k++) respawn(Math.floor(Math.random() * n));   // a little immigration
  diffuseDecay(M);

  paint();
  const ctx = p.drawingContext;
  ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
  ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
  ctx.drawImage(off, 0, 0, p.width, p.height);
  // a cheap bloom: shrink the picture, then stretch it back over itself
  bctx.imageSmoothingEnabled = true; bctx.imageSmoothingQuality = 'high';
  bctx.drawImage(off, 0, 0, 75, 75);
  ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.45;
  ctx.drawImage(bloom, 0, 0, p.width, p.height);
  ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
  const vg = ctx.createRadialGradient(400, 400, 280, 400, 400, 590);
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,0.35)');
  ctx.fillStyle = vg; ctx.fillRect(0, 0, 800, 800);
};
